int binary_search(int a[], int n, int x) {
    int low = 0;
    int high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (a[mid] == x) {
            return mid;
        }
        if (a[mid] < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

int binary_search(int a[], int n, int x) {
    int low = 0;
    int high = n - 1;
    for (; low <= high; ) {
        int mid = low + (high - low) / 2;
        if (a[mid] == x) {
            return mid;
        }
        if (x < a[mid]) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
